<?php use Addons\Grh\GrhService as S; require __DIR__ . '/_h.php'; $can = can('grh.presences') && !$locked; $prev = date('Y-m-d', strtotime($day . ' -1 day')); $next = date('Y-m-d', strtotime($day . ' +1 day')); ?>
<link rel="stylesheet" href="<?= e(asset('addons/grh/grh.css')) ?>">
<div class="d-flex flex-wrap gap-2 align-items-center mb-2"><a class="btn btn-sm btn-outline-secondary" href="<?= e(url('/grh/presences', ['jour' => $prev])) ?>"><i class="bi bi-chevron-left"></i></a>
  <form method="get" class="d-flex gap-1"><input type="date" name="jour" value="<?= e($day) ?>" max="<?= e(date('Y-m-d')) ?>" class="form-control form-control-sm"><button class="btn btn-sm btn-primary"><?= e(t('Afficher')) ?></button></form>
  <?php if ($next <= date('Y-m-d')): ?><a class="btn btn-sm btn-outline-secondary" href="<?= e(url('/grh/presences', ['jour' => $next])) ?>"><i class="bi bi-chevron-right"></i></a><?php endif; ?>
  <span class="fw-semibold ms-2"><?= e(fdate($day, false)) ?></span><?php if ($locked): ?><span class="badge text-bg-dark"><i class="bi bi-lock"></i> <?= e(t('Paie validée : mois verrouillé')) ?></span><?php endif; ?>
  <?php if (can('reports.export')): ?><a class="btn btn-sm btn-outline-success ms-auto" href="<?= e(query_with(['export' => 'csv'])) ?>"><i class="bi bi-filetype-csv"></i> <?= e(t('Mois')) ?> CSV</a><a class="btn btn-sm btn-outline-danger" href="<?= e(query_with(['export' => 'pdf'])) ?>"><i class="bi bi-filetype-pdf"></i> PDF</a><?php endif; ?></div>
<form method="post" action="<?= e(url('/grh/presences')) ?>"><?= csrf_field() ?><input type="hidden" name="day" value="<?= e($day) ?>">
<div class="card"><div class="table-responsive"><table class="table table-sm align-middle mb-0 small grh-pres"><thead><tr><th><?= e(t('Employé')) ?></th><th><?= e(t('Département')) ?></th><th><?= e(t('Pointage du jour')) ?></th><th class="text-center" title="<?= e(t('Cumul du mois')) ?>"><?= e(t('Mois : présent')) ?></th><th class="text-center"><?= e(t('retard')) ?></th><th class="text-center"><?= e(t('absent')) ?></th></tr></thead><tbody>
<?php foreach ($emps as $e): $id = (int) $e['id']; $s = $sum[$id] ?? []; ?><tr><td><a href="<?= e(url('/grh/employes/' . $id)) ?>"><?= e($e['last_name'] . ' ' . $e['first_name']) ?></a> <span class="text-secondary"><?= e($e['matricule']) ?></span></td><td><?= e($e['departement']) ?></td>
  <td><?php if ($e['conge']): ?><span class="badge text-bg-info"><?= e(t(S::LEAVE_KINDS[$e['conge']])) ?></span><?php elseif ($can): ?><div class="btn-group btn-group-sm" role="group"><?php foreach (S::PRESENCE as $k => $l): ?><input type="radio" class="btn-check" name="p[<?= $id ?>]" value="<?= e($k) ?>" id="p<?= $id . $k ?>" <?= $e['pointage'] === $k ? 'checked' : '' ?>><label class="btn btn-outline-<?= e(S::PRESENCE_COLORS[$k]) ?>" for="p<?= $id . $k ?>"><?= e(t($l)) ?></label><?php endforeach; ?></div>
    <?php else: ?><?= $e['pointage'] ? grh_badge(S::PRESENCE[$e['pointage']], S::PRESENCE_COLORS[$e['pointage']]) : '<span class="text-secondary">—</span>' ?><?php endif; ?></td>
  <td class="text-center"><?= (int) ($s['present'] ?? 0) ?></td><td class="text-center <?= ($s['retard'] ?? 0) ? 'text-warning fw-semibold' : '' ?>"><?= (int) ($s['retard'] ?? 0) ?></td><td class="text-center <?= ($s['absent'] ?? 0) ? 'text-danger fw-semibold' : '' ?>"><?= (int) ($s['absent'] ?? 0) ?></td></tr><?php endforeach; ?>
<?php if (!$emps): ?><tr><td colspan="6" class="text-center text-secondary py-4"><?= e(t('Aucun employé à cette date.')) ?></td></tr><?php endif; ?></tbody></table></div>
<?php if ($can && $emps): ?><div class="card-footer d-flex gap-2 align-items-center"><button class="btn btn-primary"><i class="bi bi-check-lg"></i> <?= e(t('Enregistrer le pointage')) ?></button><span class="small text-secondary"><?= e(t('Les absences non justifiées sont déduites du salaire à la préparation de la paie. Les congés approuvés s\'affichent tout seuls.')) ?></span></div><?php endif; ?></div></form>
